SELECT category, stock_qty_bucket, cnt, last_launch_date FROM (SELECT category, CASE WHEN stock_qty >= 420 THEN 'high' WHEN stock_qty >= 158 THEN 'mid' ELSE 'low' END AS stock_qty_bucket, COUNT(*) AS cnt, MAX(launch_date) AS last_launch_date FROM products WHERE stock_qty < 341 GROUP BY category, CASE WHEN stock_qty >= 420 THEN 'high' WHEN stock_qty >= 158 THEN 'mid' ELSE 'low' END) AS s WHERE cnt > 8
